using Godot;
using System;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWorkspaceOperations
{
    private readonly NaturalMaterialEngineOperations _naturalMaterials=new();
    public void material_edit_committed(Control owner){if(!Canvas(owner).Get("_material_busy").AsBool())commit(owner);}
    public void material_changed(Control owner,Resource value)
    {
        var canvas=Canvas(owner);if(canvas.Get("_material_busy").AsBool())return;var repair=canvas.Get("repair_tool").As<RefCounted>();repair.Set("material",_materials.copy_material(value));var document=Document(owner);var template=_documents.live_material_for_id(document,document.Get("active_live_material_id").AsString());if(document.Get("live_edit_enabled").AsBool()&&template!=null){begin(owner);_documents.set_live_material(document,template.Get("id").AsString(),value);preview(owner);}else _repair.apply_material_settings(repair,true);var swatch=owner.Get("_material_swatch").As<Button>();if(GodotObject.IsInstanceValid(swatch)){swatch.Text=value.Get("label").AsString().Left(16);material_icon_for(owner,swatch,value);}foreach(var child in owner.Get("live_material_row").As<Node>().FindChildren("*","Button",true,false))if(template!=null&&child.GetMeta("live_material_id","").AsString()==document.Get("active_live_material_id").AsString()&&child is Button button){button.Text=template.Get("label").AsString();material_icon_for(owner,button,value);}
    }
    public void painting_mode_controls(Control owner,Node host)
    {
        var canvas=Canvas(owner);var repair=canvas.Get("repair_tool").As<RefCounted>();var mode=new OptionButton{Name="PaintingMode"};mode.AddItem("Color");mode.AddItem("Material");mode.Select(canvas.Get("painting_mode").AsString()=="material"?1:0);host.AddChild(mode);mode.ItemSelected+=index=>{if(canvas.Get("_material_busy").AsBool())return;finish_pending(owner);_canvas.cancel_gesture(canvas);canvas.Set("painting_mode",index==1?"material":"color");owner.Call("_refresh_context");};if(canvas.Get("painting_mode").AsString()=="color"){context_color(owner,"Color",host);return;}var material=repair.Get("material").As<Resource>();var swatch=button(owner,host,material.Get("label").AsString().Left(16),Callable.From(()=>_browser.open(owner)),"Edit Natural Material; artwork stays visible","noise");owner.Set("_material_swatch",swatch);swatch.CustomMinimumSize=new Vector2(92,28);swatch.ExpandIcon=true;swatch.AddThemeConstantOverride("icon_max_width",28);material_icon_for(owner,swatch,material);
        SpinBox Number(string name,double min,double max,double value,string suffix,int width,string tip){var input=new DragNumber();input.Name=name;input.MinValue=min;input.MaxValue=max;input.Step=1;input.Value=value;input.Suffix=suffix;input.CustomMinimumSize=new Vector2(width,0);input.TooltipText=tip;host.AddChild(input);return input;}var extent=Number("MaterialTextureSize",2,2048,material.Get("texture_size").AsDouble(),"px",74,"Texture Size (independent of Brush Size)");void ChangeSize(double next){var copy=_materials.copy_material(repair.Get("material").As<Resource>());copy.Set("texture_size",next);material_changed(owner,copy);}extent.Connect("preview_changed",Callable.From<double>(ChangeSize));extent.ValueChanged+=next=>{ChangeSize(next);material_edit_committed(owner);};extent.Connect("drag_committed",Callable.From<double>(_=>material_edit_committed(owner)));extent.Connect("drag_cancelled",Callable.From(()=>cancel(owner)));var strength=Number("MaterialStrength",0,100,canvas.Get("material_strength").AsDouble()*100,"%",64,"Material strength");strength.ValueChanged+=next=>canvas.Set("material_strength",next/100);strength.Connect("preview_changed",Callable.From<double>(next=>canvas.Set("material_strength",next/100)));var document=Document(owner);var live=new CheckButton{Name="LiveEdit",Text="Live Edit",ButtonPressed=document.Get("live_edit_enabled").AsBool()};host.AddChild(live);live.Toggled+=enabled=>{if(canvas.Get("_material_busy").AsBool())return;finish_pending(owner);document.Set("live_edit_enabled",enabled);string id=document.Get("active_live_material_id").AsString();if(enabled&&_documents.live_material_for_id(document,id)!=null)select_live_material(owner,id);else owner.Call("_refresh_context");};
    }
    public void select_live_material(Control owner,string id)
    {
        var canvas=Canvas(owner);if(canvas.Get("_material_busy").AsBool())return;finish_pending(owner);_canvas.cancel_gesture(canvas);var document=Document(owner);var template=_documents.live_material_for_id(document,id);if(template==null)return;document.Set("active_live_material_id",id);canvas.Get("repair_tool").As<RefCounted>().Set("material",_materials.copy_material(template.Get("material").As<Resource>()));owner.Call("_refresh_context");owner.GetNodeOrNull("MaterialBrowser")?.Call("set_material_value",template.Get("material"));
    }
    public void material_icon_for(Control owner,Button button,Resource value)
    {
        string key=((long)GD.Hash(_naturalMaterials.settings_from_material(value))).ToString(System.Globalization.CultureInfo.InvariantCulture);button.SetMeta("material_thumbnail_key",key);var cache=owner.Get("_material_thumbnail_cache").AsGodotDictionary();if(cache.ContainsKey(key)){button.Icon=cache[key].As<Texture2D>();return;}var requests=owner.Get("_material_thumbnail_requests").AsGodotArray();for(int i=requests.Count-1;i>=0;i--)if(requests[i].AsGodotDictionary()["button"].As<WeakRef>().GetRef().AsGodotObject()==button)requests.RemoveAt(i);requests.Add(new Settings{["button"]=GodotObject.WeakRef(button)!,["material"]=_materials.copy_material(value),["key"]=key});if(!owner.Get("_material_thumbnail_busy").AsBool())owner.Call("_render_material_thumbnails");
    }
    public Settings next_material_thumbnail(Control owner)
    {
        owner.Set("_material_thumbnail_busy",true);var requests=owner.Get("_material_thumbnail_requests").AsGodotArray();while(requests.Count>0){var request=requests[0].AsGodotDictionary();requests.RemoveAt(0);var button=request["button"].As<WeakRef>().GetRef().AsGodotObject() as Button;if(button==null||button.GetMeta("material_thumbnail_key","").AsString()!=request["key"].AsString())continue;return request;}owner.Set("_material_thumbnail_busy",false);return new Settings();
    }
    public void complete_material_thumbnail(Control owner,Settings request,Image? bitmap)
    {
        string key=request["key"].AsString();var cache=owner.Get("_material_thumbnail_cache").AsGodotDictionary();if(!cache.ContainsKey(key)){if(bitmap==null)return;if(cache.Count>96){using var enumerator=cache.Keys.GetEnumerator();if(enumerator.MoveNext())cache.Remove(enumerator.Current);}cache[key]=ImageTexture.CreateFromImage(bitmap);}var button=request["button"].As<WeakRef>().GetRef().AsGodotObject() as Button;if(GodotObject.IsInstanceValid(button)&&button!.GetMeta("material_thumbnail_key","").AsString()==key)button.Icon=cache[key].As<Texture2D>();
    }
    public void live_material_controls(Control owner)
    {
        var canvas=Canvas(owner);var document=Document(owner);string tool=canvas.Get("tool").AsString();if(canvas.Get("painting_mode").AsString()!="material"||!document.Get("live_edit_enabled").AsBool()||tool is not "brush" and not "fill")return;owner.Get("live_material_panel").As<Control>().Show();var host=owner.Get("live_material_row").As<HBoxContainer>();var caption=new Label{Text="LIVE MATERIALS"};caption.AddThemeFontSizeOverride("font_size",11);host.AddChild(caption);button(owner,host,"+ New",Callable.From(()=>{if(canvas.Get("_material_busy").AsBool())return;Action(owner,()=>_documents.create_live_material(document,canvas.Get("repair_tool").As<RefCounted>().Get("material").As<Resource>(),""));owner.Call("_refresh_context");}),"Own a new independent set of painted regions","");var scroll=new ScrollContainer{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,CustomMinimumSize=new Vector2(150,36),VerticalScrollMode=ScrollContainer.ScrollMode.Disabled};host.AddChild(scroll);var row=new HBoxContainer();scroll.AddChild(row);foreach(var value in document.Get("live_materials").AsGodotArray()){var template=value.As<Resource>();string id=template.Get("id").AsString();var select=button(owner,row,template.Get("label").AsString(),Callable.From(()=>select_live_material(owner,id)),"Select material settings and paint more linked regions","");select.SetMeta("live_material_id",id);select.ToggleMode=true;select.SetPressedNoSignal(id==document.Get("active_live_material_id").AsString());select.ExpandIcon=true;select.AddThemeConstantOverride("icon_max_width",28);material_icon_for(owner,select,template.Get("material").As<Resource>());select.GuiInput+=input=>{if(input is InputEventMouseButton mouse&&mouse.Pressed&&mouse.ButtonIndex==MouseButton.Right)live_material_menu(owner,id);};}var bake=button(owner,host,"Bake",new Callable(owner,"_bake_active_material"),"Convert only this template's paint into raster pixels; undo available","");var remove=button(owner,host,"Delete",Callable.From(()=>delete_active_material(owner)),"Delete only this template's unbaked artwork; undo available","");bake.Disabled=document.Get("active_live_material_id").AsString().Length==0;remove.Disabled=bake.Disabled;
    }
    public void live_material_menu(Control owner,string id)
    {
        var canvas=Canvas(owner);if(canvas.Get("_material_busy").AsBool())return;var document=Document(owner);var template=_documents.live_material_for_id(document,id);if(template==null)return;var menu=new PopupMenu();owner.AddChild(menu);menu.AddItem("Rename",0);menu.AddCheckItem("Visible",1);menu.SetItemChecked(1,template.Get("visible").AsBool());menu.AddItem("Duplicate settings",2);menu.IdPressed+=action=>{if(canvas.Get("_material_busy").AsBool())return;if(action==0)name_dialog(owner,"Rename Live Material",template.Get("label").AsString(),Callable.From<string>(text=>{Action(owner,()=>template.Set("label",text));owner.Call("_refresh_context");}));else if(action==1)Action(owner,()=>template.Set("visible",!template.Get("visible").AsBool()));else Action(owner,()=>_documents.create_live_material(document,template.Get("material").As<Resource>(),template.Get("label").AsString()+" copy"));owner.Call("_refresh_context");};menu.PopupHide+=menu.QueueFree;menu.Position=(Vector2I)owner.GetGlobalMousePosition();menu.Popup();
    }
    public Settings prepare_material_bake(Control owner)
    {
        var canvas=Canvas(owner);if(canvas.Get("_material_busy").AsBool())return new Settings();finish_pending(owner);var document=Document(owner);string id=document.Get("active_live_material_id").AsString();if(_documents.live_material_for_id(document,id)==null)return new Settings();begin(owner);canvas.Set("_material_busy",true);_renderer.sync(Renderer(owner),document);return new Settings{["document"]=document,["id"]=id};
    }
    public void complete_material_bake(Control owner,Settings request,bool success)
    {
        Canvas(owner).Set("_material_busy",false);if(request["document"].AsGodotObject()!=Document(owner))return;if(success){commit(owner);owner.Get("status").As<Label>().Text="Material baked into editable pixels. Undo restores its template.";}else{cancel(owner);owner.Get("status").As<Label>().Text="Show this template before baking, then try again.";}owner.Call("_refresh_context");refresh_layers(owner);
    }
    public void delete_active_material(Control owner)
    {
        var canvas=Canvas(owner);if(canvas.Get("_material_busy").AsBool())return;var document=Document(owner);string id=document.Get("active_live_material_id").AsString();if(_documents.live_material_for_id(document,id)==null)return;void Remove(){if(canvas.Get("_material_busy").AsBool()||Document(owner)!=document)return;Action(owner,()=>_documents.delete_live_material(document,id));owner.Call("_refresh_context");owner.Get("status").As<Label>().Text="Live material and its artwork deleted. Undo restores both.";}if(!_documents.live_material_has_artwork(document,id)){Remove();return;}var dialog=new ConfirmationDialog{Title="Delete Live Material",DialogText="Delete this template and all of its unbaked artwork? Other artwork is kept. You can undo this action."};owner.AddChild(dialog);dialog.Confirmed+=()=>{Remove();dialog.QueueFree();};dialog.Canceled+=dialog.QueueFree;dialog.PopupCentered();
    }

}
